// ─────────────────────────────────────────────────────────────────────────
//  01 · group emails by domain★★☆
//  concepts: TreeMap · LinkedHashSet · unmodifiable results
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Sorted domains to their unique addresses in first-seen order, all unmodifiable. */
    static Map<String, List<String>> groupByDomain(List<String> emails) {
        var byDomain = new TreeMap<String, LinkedHashSet<String>>();
        for (var raw : emails) {
            if (raw == null) continue;
            var email = raw.strip().toLowerCase(Locale.ROOT);
            var parts = email.split("@", -1);
            if (parts.length != 2 || parts[0].isEmpty() || parts[1].isEmpty()) continue;
            byDomain.computeIfAbsent(parts[1], d -> new LinkedHashSet<>()).add(email);
        }
        var out = new TreeMap<String, List<String>>();
        byDomain.forEach((d, set) -> out.put(d, List.copyOf(set)));
        return Collections.unmodifiableMap(out);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("groups by sorted domain, unique and in order", () -> eq(groupByDomain(List.of(" Bo@b.io", "ana@a.io", "bo@b.io", "x@a.io")).toString(), "{a.io=[ana@a.io, x@a.io], b.io=[bo@b.io]}"));
        test("invalid addresses are skipped", () -> eq(groupByDomain(Arrays.asList("no-at", "a@@b.io", "@b.io", "ana@", null, "ok@c.io")).keySet(), Set.of("c.io")));
        test("the map cannot be modified", () -> raises(UnsupportedOperationException.class, () -> groupByDomain(List.of("a@x.io")).put("y.io", List.of())));
        test("the lists cannot be modified", () -> raises(UnsupportedOperationException.class, () -> groupByDomain(List.of("a@x.io")).get("x.io").add("b@x.io")));
        test("no emails gives an empty map (boundary)", () -> ok(groupByDomain(List.of()).isEmpty(), "expected an empty map"));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Collect into a `TreeMap` of `LinkedHashSet`s, then freeze everything:

```java
var byDomain = new TreeMap<String, LinkedHashSet<String>>();
for (var raw : emails) {
    if (raw == null) continue;
    var email = raw.strip().toLowerCase(Locale.ROOT);
    var parts = email.split("@", -1);
    if (parts.length != 2 || parts[0].isEmpty() || parts[1].isEmpty()) continue;
    byDomain.computeIfAbsent(parts[1], d -> new LinkedHashSet<>()).add(email);
}
var out = new TreeMap<String, List<String>>();
byDomain.forEach((d, set) -> out.put(d, List.copyOf(set)));
return Collections.unmodifiableMap(out);
```

`split("@", -1)` keeps empty trailing pieces, so `"ana@"` is rejected. `Map.copyOf` would lose the sorted order, which is why the TreeMap is wrapped instead.
